// ==UserScript==
// @name         MotionFlow for video players
// @namespace    qutebrowser-userscripts
// @version      3.2.1
// @description  Local RIFE smoothing, GPU Lanczos or optional AI upscaling, and audio compensation.
// @match        http://*/*
// @match        https://*/*
// @exclude      https://www.youtube.com/*
// @exclude      https://www.youtube-nocookie.com/*
// @grant        none
// @qute-js-world user
// @run-at       document-end
// ==/UserScript==

