        cb*=smoothstep(-0.1,0.15,foldB)*(1.0-smoothstep(4.0,8.0,foldB));
        ca*=float(all(greaterThanEqual(pa,vec2(0)))&&all(lessThanEqual(pa,vec2(1)))&&all(greaterThanEqual(endA,vec2(0)))&&all(lessThanEqual(endA,vec2(1))));
